# The engine is reached through the extern "C" entry points in embedded_mongodb_native.h --
# initialize, open, open_with_options, the three session calls, close and free, which the
# wildcard below covers without naming any of them. Everything else is internal, including
# the third-party libraries (cpptrace, libdwarf, wiredtiger, asio) whose headers mark their
# API visibility("default") and so survive -fvisibility=hidden. Hiding them is worth 1.7 MB:
# every exported symbol is a --gc-sections root.
{
    global:
        embedded_mongodb_*;
    local:
        *;
};
